// Mechanical Computer - throughput benchmark (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var tp=[12,900,120000], ef=[0.4,28,900];
console.log("Mechanical Computer - compute throughput by generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  var watts=(tp[m]/ef[m]);
  console.log("Mark "+(m+1)+": "+tp[m].toLocaleString()+" TOPS at "+ef[m]+" TOPS/W (~"+watts.toFixed(1)+" W)");
}
var job=1e18; // one exaflop of work
for(var m2=0;m2<3;m2++){ var s=job/(tp[m2]*1e12); console.log("Exaflop job on Mark "+(m2+1)+": "+(s<1?(s*1000).toFixed(1)+" ms":s.toFixed(2)+" s")); }

